# In the demo, patterns seemed to radiate from certain cells
# Maybe distance-1 neighbors of 2s change to 4?

def create_wave_pattern(grid, marker_val=2, change_to=4, dist=1):
    output = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == marker_val:
